INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind User-Stories hier nur eine Nebensache?', 2, '[{"text": "Nein", "correct": true, "because": "Sie definieren die Anforderungen"}, {"text": "Ja", "correct": false, "because": "Basis des Ablaufs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kommt direkt nach den User-Stories im Ablauf?', 3, '[{"text": "Tests schreiben", "correct": true, "because": "Test-Driven Development startet"}, {"text": "Code entwickeln", "correct": false, "because": "Folgt den Tests"}, {"text": "Ausliefern", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen sichern die Qualität im Prozess?', 5, '[{"text": "Tests schreiben", "correct": true, "because": "Fehler früh erkennen"}, {"text": "Refactoring", "correct": true, "because": "Code verbessern"}, {"text": "Einmalige Lieferung", "correct": false, "because": "Regelmäßig nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Refactoring kommt nach der Auslieferung. b) User-Stories sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "User-Stories essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was lasse ich weg, wenn ich diesen Ablauf befolge?', 4, '[{"text": "Tests schreiben", "correct": false, "because": "Kern des TDD"}, {"text": "Code entwickeln", "correct": false, "because": "Umsetzung zentral"}, {"text": "Langfristige Planung", "correct": true, "because": "Iterative Lieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal ausliefere?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßige Auslieferung"}, {"text": "Ja", "correct": false, "because": "Iterativer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich, um die Anforderungen zu klären?', 3, '[{"text": "User-Stories", "correct": true, "because": "Anforderungen definieren"}, {"text": "Tests schreiben", "correct": false, "because": "Tests erstellen"}, {"text": "Refactoring", "correct": false, "because": "Code verbessern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente fördern regelmäßige Lieferung?', 5, '[{"text": "Regelmäßig ausliefern", "correct": true, "because": "Iterative Zyklen"}, {"text": "Tests schreiben", "correct": true, "because": "Qualität sichern"}, {"text": "Einmalige Tests", "correct": false, "because": "Fortlaufend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Tests kommen vor dem Code. b) Refactoring ist einmalig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Refactoring fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "User-Stories", "correct": false, "because": "Anforderungen klären"}, {"text": "Code entwickeln", "correct": false, "because": "Umsetzung zentral"}, {"text": "Feste Deadlines", "correct": true, "because": "Flexible Iterationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Starte ich hier mit dem Code?', 2, '[{"text": "Nein", "correct": true, "because": "User-Stories und Tests zuerst"}, {"text": "Ja", "correct": false, "because": "TDD-Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte verbessern den Code?', 4, '[{"text": "Refactoring", "correct": true, "because": "Struktur optimieren"}, {"text": "Tests schreiben", "correct": true, "because": "Qualität sicherstellen"}, {"text": "Ungeprüfter Code", "correct": false, "because": "Tests zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne User-Stories arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "User-Stories sind Basis"}, {"text": "Ja", "correct": false, "because": "Anforderungen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich nach den Tests?', 3, '[{"text": "Code entwickeln", "correct": true, "because": "Tests steuern Code"}, {"text": "User-Stories", "correct": false, "because": "Vor Tests"}, {"text": "Ausliefern", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ausliefern ist regelmäßig. b) Tests sind nach dem Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests vor Code"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Hohe Qualität", "correct": true, "because": "Tests und Refactoring"}, {"text": "Schnelle Lieferung", "correct": true, "because": "Regelmäßige Auslieferung"}, {"text": "Langfristige Planung", "correct": false, "because": "Iterativ fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Tests schreiben", "correct": false, "because": "Qualität sichern"}, {"text": "Refactoring", "correct": false, "because": "Code verbessern"}, {"text": "Einmalige Lieferung", "correct": true, "because": "Regelmäßig nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Refactoring hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Code kontinuierlich verbessern"}, {"text": "Ja", "correct": false, "because": "Qualität steigern"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Tests arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Tests schreiben ist Kern"}, {"text": "Ja", "correct": false, "because": "TDD zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Auslieferung?', 4, '[{"text": "Refactoring", "correct": true, "because": "Code verbessern"}, {"text": "Tests schreiben", "correct": false, "because": "Vor Code"}, {"text": "User-Stories", "correct": false, "because": "Start des Zyklus"}]');
